CREATE OR REPLACE FUNCTION public.tg_notify_food_reaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT name INTO t FROM public.foods WHERE id = NEW.food_id; PERFORM public.notify_members(NEW.member_id, 'food_reaction', COALESCE(t, '') || '|' || NEW.emoji); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_notify_food_comment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT name INTO t FROM public.foods WHERE id = NEW.food_id; PERFORM public.notify_members(NEW.member_id, 'food_comment', COALESCE(t, '')); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_notify_activity_reaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT name INTO t FROM public.activities WHERE id = NEW.activity_id; PERFORM public.notify_members(NEW.member_id, 'activity_reaction', COALESCE(t, '') || '|' || NEW.emoji); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_notify_activity_comment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT name INTO t FROM public.activities WHERE id = NEW.activity_id; PERFORM public.notify_members(NEW.member_id, 'activity_comment', COALESCE(t, '')); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_notify_memory_reaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT title INTO t FROM public.memories WHERE id = NEW.memory_id; PERFORM public.notify_members(NEW.member_id, 'memory_reaction', COALESCE(t, '') || '|' || NEW.emoji); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_notify_memory_comment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE t text; BEGIN SELECT title INTO t FROM public.memories WHERE id = NEW.memory_id; PERFORM public.notify_members(NEW.member_id, 'memory_comment', COALESCE(t, '')); RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.tg_notify_food_reaction(), public.tg_notify_food_comment(), public.tg_notify_activity_reaction(), public.tg_notify_activity_comment(), public.tg_notify_memory_reaction(), public.tg_notify_memory_comment() FROM PUBLIC, anon, authenticated;